Here is a Python implementation using integer cents. Discount codes represent fixed amounts and can each be applied once per cart.

```python
from dataclasses import dataclass, field


@dataclass
class Cart:
    # Map discount codes to their values in cents.
    discount_codes: dict[str, int]
    items: list[tuple[int, int]] = field(default_factory=list)
    applied_codes: set[str] = field(default_factory=set)

    def __post_init__(self) -> None:
        # Copy the mapping so external changes don't alter the cart's discounts.
        self.discount_codes = dict(self.discount_codes)
        for code, amount in self.discount_codes.items():
            if not code or type(amount) is not int or amount < 0:
                raise ValueError("Discount codes need nonnegative integer amounts")

    def add_item(self, price_cents: int, quantity: int) -> None:
        if type(price_cents) is not int or price_cents < 0:
            raise ValueError("Price must be a nonnegative integer number of cents")
        if type(quantity) is not int or quantity <= 0:
            raise ValueError("Quantity must be a positive integer")
        self.items.append((price_cents, quantity))

    def apply_discount(self, code: str) -> None:
        if code not in self.discount_codes:
            raise ValueError("Unknown discount code")
        if code in self.applied_codes:
            raise ValueError("Discount code has already been applied")
        self.applied_codes.add(code)

    def final_price_cents(self) -> int:
        subtotal = sum(price * quantity for price, quantity in self.items)
        discount = sum(self.discount_codes[code] for code in self.applied_codes)
        return max(0, subtotal - discount)


cart = Cart(discount_codes={"SAVE5": 500, "SAVE10": 1000})
cart.add_item(price_cents=1299, quantity=2)
cart.apply_discount("SAVE5")

cents = cart.final_price_cents()
print(f"${cents // 100}.{cents % 100:02d}")  # $20.98
```

